1	package netdiag
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"reflect"
8		"strings"
9		"testing"
10	
11		tea "charm.land/bubbletea/v2"
12		"github.com/charmbracelet/x/ansi"
13	
14		"github.com/anthnel/devdesk/internal/ui/components"
15		"github.com/anthnel/devdesk/internal/ui/indicator"
16		"github.com/anthnel/devdesk/internal/ui/keymap"
17		"github.com/anthnel/devdesk/internal/ui/testutil"
18	)
19	
20	// DEVDESK-150 step 2: the footer of the selected row during a kill (A-05), the
21	// legend in the help (Rule 114), and the shortcut set staying put (Rule 130).
22	
23	const killingSSHDLine = "Killing sshd (812)"
24	
25	// portsFooter is the rendered footer of the Ports tab, escape sequences removed.
26	func portsFooter(m *Model, width int) string { return ansi.Strip(m.RenderFooter(width)) }
27	
28	// infoLine is the last line of the footer: the message / status line.
29	func infoLine(m *Model, width int) string {
30		lines := strings.Split(portsFooter(m, width), "\n")
31		return strings.TrimSpace(lines[len(lines)-1])
32	}
33	
34	func TestTheFooterNamesTheKillOfTheSelectedRow(t *testing.T) {
35		m := killingSSHD(t)
36		want := components.DescribeRow(components.RowQuery{
37			Observed: indicator.Running, ObservedText: killingSSHDLine,
38		}).Detail
39	
40		status := m.portsModel.statusLine()
41		if status.Detail != want {
42			t.Fatalf("status Detail = %+v, want the DescribeRow detail %+v", status.Detail, want)
43		}
44		if status.Level != components.LevelInfo {
45			t.Errorf("status Level = %v, want Info", status.Level)
46		}
47		line := infoLine(m, 120)
48		if wantLine := indicator.Glyph(indicator.Running, true) + " " + killingSSHDLine; !strings.Contains(line, wantLine) {
49			t.Errorf("footer line = %q, want it to contain %q", line, wantLine)
50		}
51	}
52	
53	func TestTheFooterOnlyDescribesTheSelectedRow(t *testing.T) {
54		m := feed(t, killingSSHD(t), testutil.Key("down")) // cursor on nginx, not busy
55		if !m.portsModel.statusLine().Detail.IsZero() {
56			t.Errorf("an idle selected row carries a detail: %+v", m.portsModel.statusLine().Detail)
57		}
58		if line := infoLine(m, 120); hasAnyActivityGlyph(line) || strings.Contains(line, "Killing") {
59			t.Errorf("footer line = %q for a row nothing is happening on", line)
60		}
61	}
62	
63	func TestTheKillDetailComesBeforeThePause(t *testing.T) {
64		m := feed(t, killingSSHD(t), testutil.Key(" "))
65		line := infoLine(m, 120)
66		kill, paused := strings.Index(line, killingSSHDLine), strings.Index(line, "Paused — press space to resume")
67		if kill < 0 || paused < 0 || kill > paused {
68			t.Errorf("footer line = %q, want the kill detail then the pause text on one line", line)
69		}
70	}
71	
72	func TestTheKillDetailComesBeforeTheStaleText(t *testing.T) {
73		m := feed(t, killingSSHD(t), portsDataMsg{err: errors.New("ss failed")})
74		status := m.portsModel.statusLine()
75		if status.Level != components.LevelError {
76			t.Errorf("status Level = %v, want Error while stale", status.Level)
77		}
78		line := infoLine(m, 120)
79		kill, stale := strings.Index(line, killingSSHDLine), strings.Index(line, "could not be read")
80		if kill < 0 || stale < 0 || kill > stale {
81			t.Errorf("footer line = %q, want the kill detail then the stale text", line)
82		}
83	}
84	
85	func TestAFailedKillStaysAFooterErrorWithoutTheFailedGlyph(t *testing.T) {
86		m := feed(t, killingSSHD(t), portsKillResultMsg{pid: "812", err: fmt.Errorf("killing: %w", os.ErrPermission)})
87	
88		if got := m.portsModel.footer.Level(); got != components.LevelError {
89			t.Errorf("footer level = %v, want Error", got)
90		}
91		line := infoLine(m, 120)
92		if !strings.Contains(line, "Refused by the system") {
93			t.Errorf("footer line = %q, want the refusal to win", line)
94		}
95		for _, on := range []bool{true, false} {
96			if g := indicator.Glyph(indicator.Failed, on); strings.Contains(portsFooter(m, 120), g) || strings.Contains(m.portsModel.table.View(), g) {
97				t.Errorf("a failed kill shows %q: this view remembers no failure (D5)", g)
98			}
99		}
100		if !m.portsModel.statusLine().Detail.IsZero() {
101			t.Errorf("the row is at rest, yet the status carries %+v", m.portsModel.statusLine().Detail)
102		}
103	
104		m = feed(t, m, components.ClearFooterMsg{ID: m.portsModel.footer.ID()})
105		if line := infoLine(m, 120); hasAnyActivityGlyph(line) || strings.Contains(line, "Killing") {
106			t.Errorf("footer line = %q after the error expired, want nothing about the row", line)
107		}
108	}
109	
110	func TestTheKillDetailKeepsTheFooterOnOneLineAt60Columns(t *testing.T) {
111		idle := feed(t, portsModel(t), tea.WindowSizeMsg{Width: 60, Height: 30})
112		busy := feed(t, killingSSHD(t), tea.WindowSizeMsg{Width: 60, Height: 30})
113	
